  function flower5(c,x,y,r,pal){part(c,m=>{for(let k=0;k<5;k++){const an=k*1.2566-1.57;m.ell(x+Math.cos(an)*r*.9,y+Math.sin(an)*r*.9,r*.75,r*.75,'x');}m.ell(x,y,r*.6,r*.6,'x');},pal,{line:true});c.ell(x,y,r*.32,r*.32,'#f4d878');}
