      const by = (b.y - t * 0.03 * b.speed) % 80;
      const py = cy + (by < 0 ? by + 80 : by) * (sc || 1) - 40;
      const px = cx + (b.x + Math.sin(t * 0.002 + b.speed) * 8) * (sc || 1);
